  .rank { font-size:20px; fill:#77A7CA; font-weight:900; }
  .company { font-size:19px; fill:#EAF6FF; font-weight:850; }
  .ticker { font-size:15px; fill:#6F91AE; font-weight:700; }
  .cap { font-size:22px; fill:#FFFFFF; font-weight:900; }
