  .pillText { font-size:14px; fill:#B9CBE0; font-weight:750; }
  .pillValue { font-size:17px; fill:#FFFFFF; font-weight:950; }
  .contextBig { font-size:68px; fill:#F6FBFF; font-weight:950; letter-spacing:-3px; }
  .contextMed { font-size:26px; fill:#76F7D1; font-weight:900; }
