<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <radialGradient id="halo" cx="35%" cy="8%" r="75%">
      <stop offset="0" stop-color="#123A63" stop-opacity="1"/>
      <stop offset="0.45" stop-color="#071B2E" stop-opacity="0.72"/>
      <stop offset="1" stop-color="#07111F" stop-opacity="1"/>
    </radialGradient>
    <linearGradient id="nvidiaGrad" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="#76F7D1"/><stop offset="0.5" stop-color="#B6F56A"/><stop offset="1" stop-color="#F5C35E"/>
    </linearGradient>
    <linearGradient id="blueGrad" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="#2D7CFF"/><stop offset="1" stop-color="#5EE7FF"/>
    </linearGradient>
    <linearGradient id="panelGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#10243D" stop-opacity="0.96"/><stop offset="1" stop-color="#0A1829" stop-opacity="0.96"/>
    </linearGradient>
    <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
      <path d="M40 0H0V40" fill="none" stroke="#17314B" stroke-width="1" opacity="0.35"/>
    </pattern>
    <filter id="glow" x="-30%" y="-30%" width="160%" height="160%">
      <feGaussianBlur stdDeviation="8" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
  </defs>

  <rect width="${W}" height="${H}" fill="url(#halo)"/>
  <rect width="${W}" height="${H}" fill="url(#grid)"/>
