      <circle cx="0" cy="0" r="8" fill="#5EE7FF"/><text x="18" y="6" class="countryText">United States</text>
      <circle cx="182" cy="0" r="8" fill="#F5C35E"/><text x="200" y="6" class="countryText">Other markets</text>
    </g>
  </g>

  <g transform="translate(760 910)">
    <rect x="0" y="0" width="370" height="286" rx="24" fill="url(#panelGrad)" stroke="#1E4667"/>
    <text x="28" y="48" class="sectionTitle">Sector Concentration</text>
    <text x="30" y="82" class="sectionNote">Top 11 composition by business type</text>
  </g>
  ${sectorPills}

  <g transform="translate(70 1262)">
    <rect x="0" y="0" width="1060" height="350" rx="30" fill="url(#panelGrad)" stroke="#1E4667"/>
    <text x="34" y="56" class="sectionTitle">Putting It in Perspective</text>
    <text x="34" y="95" class="sectionNote">Nearly 11,000 tracked public companies are worth $142.9T combined.</text>

    <g transform="translate(34 138)">
      <text x="0" y="58" class="contextBig">$25.4T</text>
      <text x="0" y="94" class="contextMed">Top 10 combined market cap</text>
      <text x="0" y="130" class="contextText">Just 0.09% of companies hold roughly 17.8% of total tracked value.</text>
      <rect x="0" y="168" width="620" height="30" rx="15" fill="#12263E"/>
      <rect x="0" y="168" width="110" height="30" rx="15" fill="url(#nvidiaGrad)" filter="url(#glow)"/>
      <text x="635" y="191" class="contextText">17.8% of $142.9T</text>
    </g>

    <g transform="translate(748 114)">
      <circle cx="130" cy="98" r="94" fill="none" stroke="#132A43" stroke-width="24"/>
      <circle cx="130" cy="98" r="94" fill="none" stroke="url(#blueGrad)" stroke-width="24" stroke-linecap="round" stroke-dasharray="105.1 590" transform="rotate(-90 130 98)"/>
      <text x="130" y="88" text-anchor="middle" class="contextBig" style="font-size:52px">18%</text>
      <text x="130" y="122" text-anchor="middle" class="metricLabel">of total value</text>
    </g>
  </g>

  <g transform="translate(70 1660)">
    <rect x="0" y="0" width="1060" height="72" rx="18" fill="#091827" stroke="#173B59"/>
    <text x="24" y="30" class="footer">Source: CompaniesMarketCap-style global public company market capitalization snapshot, mid-2025. Values rounded.</text>
    <text x="24" y="54" class="footer">Key gap: rank #1 NVIDIA at $4.82T vs. rank #20 at roughly $554B — nearly a 9× valuation drop.</text>
  </g>
</svg>
</body>
</html>`;

